#!/usr/bin/env python3
"""Test vectors for apple/reports, generated by running the REAL FindMy.py (the oracle) on fixed synthetic inputs.

    python app/tools/oracle/reports_vectors.py

Writes android/app/src/test/resources/fixtures/reports/{keys,alignment,accessory_json,decrypt,fetch}.json.
Everything is derived from fixed seeds: no real key, token or account is involved. Deterministic: run it twice, get the
same files (the time zone is pinned to UTC for the one place a naive datetime would otherwise matter).
"""

from __future__ import annotations

import asyncio
import base64
import hashlib
import json
import os
import struct
from datetime import datetime, timedelta, timezone
from pathlib import Path

os.environ["TZ"] = "UTC"

from cryptography.hazmat.primitives import serialization  # noqa: E402
from cryptography.hazmat.primitives.asymmetric import ec  # noqa: E402
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes  # noqa: E402

import findmy.reports.reports as reports_mod  # noqa: E402
from findmy.accessory import FindMyAccessory, _extract_serial_from_stable_id  # noqa: E402
from findmy.keys import KeyPair, KeyPairType  # noqa: E402
from findmy.reports.reports import LocationReport, LocationReportsFetcher  # noqa: E402
from findmy.util import crypto  # noqa: E402

OUT = Path(__file__).resolve().parents[2] / "android/app/src/test/resources/fixtures/reports"
B64 = lambda b: base64.b64encode(b).decode()  # noqa: E731


def seed(label: str, n: int) -> bytes:
    return hashlib.sha256(b"osfind-reports-oracle:" + label.encode()).digest()[:n]


def accessory(label: str, **kw) -> FindMyAccessory:
    return FindMyAccessory(
        master_key=seed(label + ":master", 28), skn=seed(label + ":skn", 32), sks=seed(label + ":sks", 32),
        paired_at=kw.pop("paired_at", datetime(2026, 9, 1, tzinfo=timezone.utc)), **kw)


def dump(name: str, data) -> None:
    OUT.mkdir(parents=True, exist_ok=True)
    (OUT / name).write_text(json.dumps(data, indent=1, sort_keys=True) + "\n")


def key_json(k: KeyPair) -> dict:
    return {"priv": k.private_key_bytes.hex(), "adv": B64(k.adv_key_bytes), "hashed": k.hashed_adv_key_b64}


# ---------------------------------------------------------------------------------------------------- keys
def gen_keys() -> None:
    out = {"kdf": [], "derive": [], "keypairs": [], "accessories": []}
    for si, length in [(b"update", 32), (b"diversify", 72), (b"x", 1), (b"", 33), (b"update", 64)]:
        v = seed("kdf" + str(length), 32)
        out["kdf"].append({"value": v.hex(), "si": si.hex(), "length": length, "out": crypto.x963_kdf(v, si, length).hex()})
    for i in range(4):
        out["derive"].append({"master": seed(f"d{i}m", 28).hex(), "sk": seed(f"d{i}s", 32).hex(),
                              "out": crypto.derive_ps_key(seed(f"d{i}m", 28), seed(f"d{i}s", 32)).hex()})
    n_minus_1 = (crypto.P224_N - 1).to_bytes(28, "big")
    for priv in [(1).to_bytes(28, "big"), n_minus_1, seed("kp0", 28), seed("kp1", 28)]:
        out["keypairs"].append({"priv": priv.hex(), **key_json(KeyPair(priv))})
    for label in ["accA", "accB"]:
        acc = accessory(label)
        entry = {"master": acc.master_key.hex(), "skn": acc.skn.hex(), "sks": acc.sks.hex(), "primary": {}, "secondary": {}, "keys_at": {}}
        for i in [0, 1, 2, 3, 4, 5, 95, 96, 97, 191, 192, 193, 287, 288, 671, 672, 673, 700, 2880]:
            entry["primary"][str(i)] = key_json(acc._primary_gen[i])
        for i in range(0, 12):
            entry["secondary"][str(i)] = key_json(acc._secondary_gen[i])
        # out-of-order access exercises the checkpoint cache of the generator
        for i in [700, 5, 3000, 2999, 4, 672, 673]:
            entry["primary"][str(i)] = key_json(acc._primary_gen[i])
        for i in [-1, 0, 1, 95, 96, 97, 190, 191, 192, 400]:
            ks = acc.keys_at(i)
            entry["keys_at"][str(i)] = sorted(({"type": k.key_type.name, "hashed": k.hashed_adv_key_b64} for k in ks), key=lambda d: d["hashed"])
        out["accessories"].append(entry)
    # keys_between: deduplicated (first index, key) over index and time ranges that straddle rollovers
    base = datetime(2026, 10, 1, 12, 0, tzinfo=timezone.utc)
    acc = accessory("accA", alignment_date=base, alignment_index=1000)
    out["between"] = []

    def between(label, start, end):
        items = [{"index": i, "type": k.key_type.name, "hashed": k.hashed_adv_key_b64} for i, k in acc.keys_between(start, end)]
        out["between"].append({"name": label, "start": start.isoformat() if isinstance(start, datetime) else start,
                               "end": end.isoformat() if isinstance(end, datetime) else end, "items": items})

    between("indices_around_secondary_rollover_95_97", 95, 97)
    between("indices_around_secondary_rollover_190_194", 190, 194)
    between("single_index", 7, 7)
    between("negative_start", -2, 1)
    between("time_around_15min_rollover", base + timedelta(minutes=14), base + timedelta(minutes=16))
    between("time_straddling_alignment", base - timedelta(minutes=40), base + timedelta(minutes=20))
    between("time_across_a_secondary_rollover", base + timedelta(hours=23, minutes=50), base + timedelta(days=1, minutes=10))
    out["between_accessory"] = acc.to_json()
    dump("keys.json", out)


# ------------------------------------------------------------------------------------------------ alignment
def gen_alignment() -> None:
    base = datetime(2026, 10, 1, 12, 0, tzinfo=timezone.utc)
    acc = accessory("accA", alignment_date=base, alignment_index=1000)
    q = [base - timedelta(days=7), base - timedelta(hours=1), base - timedelta(minutes=14, seconds=59), base - timedelta(minutes=15),
         base - timedelta(seconds=1), base, base + timedelta(seconds=1), base + timedelta(minutes=14, seconds=59, microseconds=999999),
         base + timedelta(minutes=15), base + timedelta(minutes=29, seconds=59), base + timedelta(days=3, minutes=7), base + timedelta(days=7)]
    out = {"accessory": acc.to_json(), "queries": [], "updates": []}
    for dt in q:
        out["queries"].append({"at": dt.isoformat(), "min": acc.get_min_index(dt), "max": acc.get_max_index(dt)})
    seq = [(base - timedelta(hours=1), 1100), (base + timedelta(hours=1), 900), (base + timedelta(hours=2), 1004), (base + timedelta(hours=1, minutes=30), 1010),
           (base + timedelta(hours=2), 1004), (base + timedelta(hours=3), 1004), (base + timedelta(hours=3), 1003), (base + timedelta(hours=5), 5000)]
    for dt, idx in seq:
        acc.update_alignment(dt, idx)
        out["updates"].append({"at": dt.isoformat(), "index": idx, "alignment_date": acc._alignment_date.isoformat(), "alignment_index": acc._alignment_index,
                               "min": acc.get_min_index(base + timedelta(days=1)), "max": acc.get_max_index(base + timedelta(days=1))})
    dump("alignment.json", out)


# ------------------------------------------------------------------------------------------- accessory JSON
def gen_accessory_json() -> None:
    tz530 = timezone(timedelta(hours=5, minutes=30))
    tzm = timezone(-timedelta(hours=8))
    variants = {
        "utc": accessory("accA", name="Keys", model="AirTag1,1", identifier="ID-1", group_identifier="G", serial_number="SER1",
                         alignment_date=datetime(2026, 10, 2, 3, 4, 5, tzinfo=timezone.utc), alignment_index=77),
        "offset+5:30_micro": accessory("accB", paired_at=datetime(2026, 8, 1, 10, 20, 30, 123456, tzinfo=tz530), name="Bag", model=None,
                                       identifier="ID-2", alignment_date=datetime(2026, 8, 2, 1, 2, 3, 654321, tzinfo=tzm), alignment_index=5),
        "nulls": accessory("accC", name=None, model=None, identifier=None),
    }
    cases = []
    for name, acc in variants.items():
        cases.append({"name": name, "input": acc.to_json(), "python_roundtrip": FindMyAccessory.from_json(acc.to_json()).to_json()})
    # older exports lack group_identifier/serial_number; Z suffix and space separator are accepted by fromisoformat
    older = dict(variants["utc"].to_json())
    del older["group_identifier"], older["serial_number"]
    older["paired_at"] = "2026-09-01T00:00:00Z"
    cases.append({"name": "older_export", "input": older, "python_roundtrip": FindMyAccessory.from_json(older).to_json()})
    spaced = dict(variants["utc"].to_json())
    spaced["paired_at"] = "2026-09-01 07:08:09+02:00"
    cases.append({"name": "space_separator", "input": spaced, "python_roundtrip": FindMyAccessory.from_json(spaced).to_json()})
    nulled = dict(variants["utc"].to_json())
    nulled["alignment_date"] = None
    nulled["alignment_index"] = None
    cases.append({"name": "null_alignment", "input": nulled, "python_roundtrip": FindMyAccessory.from_json(nulled).to_json()})

    bad = []
    good = variants["utc"].to_json()

    def attempt(label: str, doc: dict) -> None:
        try:
            FindMyAccessory.from_json(doc)
            raise SystemExit(f"oracle accepted malformed case {label}")
        except (ValueError, KeyError, AssertionError, TypeError):
            bad.append({"name": label, "input": doc})

    for f in ["master_key", "skn", "sks", "paired_at", "name", "model", "identifier", "alignment_date", "alignment_index"]:
        d = dict(good)
        del d[f]
        attempt("missing_" + f, d)
    attempt("master_short", {**good, "master_key": good["master_key"][:-2]})
    attempt("skn_short", {**good, "skn": good["skn"][:-2]})
    attempt("bad_hex", {**good, "sks": "zz" * 32})
    attempt("wrong_type", {**good, "type": "keypair"})
    attempt("bad_date", {**good, "paired_at": "yesterday"})

    stable = [None, [], ["2006~#hw~#SERIAL1"], ["a:/uuid~#SER2"], ["nodelimiter"], ["a:/u~#\u00b6M\u00a7hw\u00a7" + b"C02XYZ".hex() + "\u00a70"],
              ["a:/u~#\u00b6M\u00a7hw"], ["a:/u~#\u00b6M\u00a7hw\u00a7zz\u00a70"], ["a:/u~#\u00b6M\u00a7hw\u00a7ff\u00a70"], ["x~#y~#z", "ignored~#other"]]
    serials = [{"input": s, "out": _extract_serial_from_stable_id(s)} for s in stable]
    dump("accessory_json.json", {"cases": cases, "bad": bad, "serials": serials})


# --------------------------------------------------------------------------------------------------- decrypt
def encrypt_report(key: KeyPair, ts: datetime, lat: float, lon: float, acc: int, status: int, conf: int, fmt: int = 88, eph_label: str = "eph") -> bytes:
    """The OpenHaystack scheme from the sender's side: ephemeral key, ECDH to the tag's public key, SHA-256 KDF, AES-GCM."""
    eph = ec.derive_private_key(int.from_bytes(seed(eph_label + str(ts.timestamp()), 28), "big"), ec.SECP224R1())
    eph_pub = eph.public_key().public_bytes(serialization.Encoding.X962, serialization.PublicFormat.UncompressedPoint)
    assert len(eph_pub) == 57
    tag_pub = key._priv_key.public_key()
    shared = eph.exchange(ec.ECDH(), tag_pub)
    sym = hashlib.sha256(shared + b"\x00\x00\x00\x01" + eph_pub).digest()
    enc = Cipher(algorithms.AES(sym[:16]), modes.GCM(sym[16:])).encryptor()
    plain = struct.pack(">ii", round(lat * 1e7), round(lon * 1e7)) + bytes([acc, status])
    ct = enc.update(plain) + enc.finalize()
    stamp = struct.pack(">I", int(ts.timestamp()) - 978307200)
    if fmt == 88:
        return stamp + bytes([conf]) + eph_pub + ct + enc.tag
    return stamp + bytes([0x55, conf]) + eph_pub + ct + enc.tag


def py_decrypt(payload: bytes, hashed: bytes, key: KeyPair) -> dict:
    r = LocationReport(payload, hashed)
    try:
        r.decrypt(key)
        return {"ok": True, "lat": r.latitude, "lon": r.longitude, "acc": r.horizontal_accuracy, "status": r.status,
                "conf": r.confidence, "ts": int(r.timestamp.timestamp())}
    except Exception as e:  # noqa: BLE001
        return {"ok": False, "why": type(e).__name__}


def gen_decrypt() -> None:
    key = KeyPair(seed("tag", 28), KeyPairType.PRIMARY)
    other = KeyPair(seed("other", 28))
    t0 = datetime(2026, 10, 1, 8, 30, 15, tzinfo=timezone.utc)
    specs = [(48.8566, 2.3522, 17, 0, 3, 88), (-33.8688, 151.2093, 255, 129, 1, 88), (-0.0001, -179.9999, 0, 255, 2, 89),
             (37.7749, -122.4194, 5, 4, 3, 89), (0.5, 0.25, 65, 32, 1, 88)]
    valid = []
    for i, (lat, lon, acc, st, conf, fmt) in enumerate(specs):
        p = encrypt_report(key, t0 + timedelta(minutes=17 * i), lat, lon, acc, st, conf, fmt)
        valid.append({"payload": B64(p), "hashed": key.hashed_adv_key_b64, "py": py_decrypt(p, key.hashed_adv_key_bytes, key), "fmt": fmt})
        assert valid[-1]["py"]["ok"] and abs(valid[-1]["py"]["lat"] - lat) < 1e-6
    good = encrypt_report(key, t0, 12.3456789, 98.7654321, 9, 8, 2, 88)
    other_good = encrypt_report(other, t0, 1.0, 2.0, 3, 4, 1, 88)
    malformed = []

    def add(label: str, payload: bytes, hashed: bytes | None = None) -> None:
        h = key.hashed_adv_key_bytes if hashed is None else hashed
        malformed.append({"name": label, "payload": B64(payload), "hashed": B64(h), "py": py_decrypt(payload, h, key)})

    def flip(p: bytes, i: int) -> bytes:
        return p[:i] + bytes([p[i] ^ 1]) + p[i + 1:]

    add("valid_control", good)
    add("empty", b"")
    add("three_bytes", good[:3])
    add("ts_only", good[:4])
    add("truncated_10", good[:10])
    add("truncated_60", good[:60])
    add("truncated_87", good[:87])
    add("one_short_of_89", good + b"\x00")
    add("trailing_bytes_90", good + b"\x00\x00")
    add("trailing_bytes_100", good + b"\x00" * 12)
    add("flipped_mac_first", flip(good, 72))
    add("flipped_mac_last", flip(good, 87))
    add("flipped_ciphertext", flip(good, 64))
    add("flipped_ephemeral_y", flip(good, 5 + 40))
    add("ephemeral_not_uncompressed", good[:5] + b"\x02" + good[6:])
    add("ephemeral_off_curve", good[:6 + 20] + b"\xff" * 4 + good[6 + 24:])
    add("ephemeral_zeroed", good[:5] + b"\x00" * 57 + good[62:])
    add("wrong_key_report", other_good)
    add("wrong_hashed_id", good, hashlib.sha256(b"x").digest())
    add("bad_timestamp_bytes_ok", b"\xff\xff\xff\xff" + good[4:])
    add("format89_ok", encrypt_report(key, t0, 1.5, 2.5, 3, 4, 2, 89))
    add("format89_truncated", encrypt_report(key, t0, 1.5, 2.5, 3, 4, 2, 89)[:-1])
    for n in range(80, 96):  # every length around the two valid ones, padded with zeros or cut
        p = (good + b"\x00" * 20)[:n]
        add(f"len_{n}", p)
    dump("decrypt.json", {"key": key.private_key_bytes.hex(), "hashed": key.hashed_adv_key_b64, "valid": valid, "malformed": malformed,
                          "tag_public": B64(key.adv_key_bytes)})


# ----------------------------------------------------------------------------------------------------- fetch
class _FakeAccount:
    """What `LocationReportsFetcher` needs from an account: records each request, answers from a script."""

    def __init__(self, script: list[list[tuple[bytes, bytes]]]) -> None:
        self.script = script
        self.calls: list[list[tuple[list[str], list[str]]]] = []

    async def fetch_raw_reports(self, devices):  # noqa: ANN001
        self.calls.append([(list(p), list(s)) for p, s in devices])
        i = len(self.calls) - 1
        return [LocationReport(payload, hashed) for hashed, payload in (self.script[i] if i < len(self.script) else [])]


def _freeze(now: datetime):
    class FrozenDatetime(datetime):
        @classmethod
        def now(cls, tz=None):  # noqa: ANN001, ANN206
            return now if tz is None else now.astimezone(tz)

    reports_mod.datetime = FrozenDatetime


def _digest(ids: list[str]) -> dict:
    s = sorted(ids)
    return {"count": len(s), "sha256": hashlib.sha256("\n".join(s).encode()).hexdigest(), "ids": s if len(s) <= 20 else None}


def _summ_reports(rs) -> list[dict]:
    return [{"ts": int(r.timestamp.timestamp()), "lat": r.latitude, "lon": r.longitude, "acc": r.horizontal_accuracy, "status": r.status,
             "conf": r.confidence, "hashed": B64(r.hashed_adv_key_bytes)} for r in rs]


def _enc(key: KeyPair, ts: datetime, lat: float, lon: float, acc: int, st: int, conf: int = 2, fmt: int = 88):
    return key.hashed_adv_key_bytes, encrypt_report(key, ts, lat, lon, acc, st, conf, fmt)


def _run_rolling(label: str, acc: FindMyAccessory, now: datetime, script_builder, only_latest: bool) -> dict:
    _freeze(now)
    scenario_acc = FindMyAccessory.from_json(acc.to_json())
    fake = _FakeAccount(script_builder(scenario_acc))
    fetcher = LocationReportsFetcher(fake)
    result = asyncio.run(fetcher._fetch_accessory_reports(scenario_acc, only_latest=only_latest))
    return {
        "name": label, "accessory": acc.to_json(), "now": now.isoformat(), "only_latest": only_latest,
        "calls": [[{"primary": _digest(p), "secondary": _digest(s)} for p, s in call] for call in fake.calls],
        "replies": [[{"hashed": B64(h), "payload": B64(p)} for h, p in step] for step in fake.script],
        "reports": _summ_reports(result),
        "alignment_epoch": int(scenario_acc._alignment_date.timestamp()), "alignment_index": scenario_acc._alignment_index,
    }


def gen_fetch() -> None:
    scenarios = []
    now_a = datetime(2026, 10, 3, 12, 0, tzinfo=timezone.utc)
    acc_a = accessory("accA", name="A", identifier="A-ID", paired_at=datetime(2026, 10, 1, tzinfo=timezone.utc))

    def script_a(order_primary_first: bool):
        def build(a):
            t1 = datetime(2026, 10, 3, 11, 0, 7, tzinfo=timezone.utc)
            t2 = datetime(2026, 10, 3, 10, 0, 3, tzinfo=timezone.utc)
            prim = _enc(a._primary_gen[100], t1, 48.85, 2.35, 12, 1, 3)        # key index 100
            sec = _enc(a._secondary_gen[2], t2, 48.86, 2.36, 40, 2, 1, 89)     # secondary 2: indices 0..191
            return [[prim, sec] if order_primary_first else [sec, prim]]
        return build

    scenarios.append(_run_rolling("single_request_primary_then_secondary", acc_a, now_a, script_a(True), True))
    scenarios.append(_run_rolling("single_request_secondary_then_primary", acc_a, now_a, script_a(False), True))
    def script_invalid(a):
        ok = _enc(a._primary_gen[50], datetime(2026, 10, 3, 9, 0, 0, tzinfo=timezone.utc), 40.0, 8.0, 20, 1, 3)
        null_island = _enc(a._primary_gen[60], datetime(2026, 10, 3, 10, 0, 0, tzinfo=timezone.utc), 0.0, 0.0, 20, 1, 3)
        future = _enc(a._primary_gen[70], datetime(2026, 10, 3, 13, 0, 0, tzinfo=timezone.utc), 41.0, 9.0, 20, 1, 3)
        return [[ok, null_island, future]]

    scenarios.append(_run_rolling("single_request_invalid_by_domain_rules", acc_a, now_a, script_invalid, True))
    scenarios.append(_run_rolling("single_request_no_reports", acc_a, now_a, lambda a: [[]], True))

    # a long walk: 7 requests of at most 290 ids; the second one carries a report, so only_latest stops there
    acc_b = accessory("accB", name="B", identifier="B-ID", paired_at=datetime(2026, 9, 1, tzinfo=timezone.utc),
                      alignment_date=datetime(2026, 9, 20, tzinfo=timezone.utc), alignment_index=1800)
    now_b = datetime(2026, 10, 10, 0, 0, tzinfo=timezone.utc)

    def script_b(a):
        # walks down from index 3720 in 290-id steps: call 2 holds indices 3430 .. 3141
        t = datetime(2026, 10, 9, 22, 0, 0, tzinfo=timezone.utc)
        return [[], [_enc(a._primary_gen[3300], t, -22.9068, -43.1729, 33, 0, 2)]]

    scenarios.append(_run_rolling("chunked_only_latest", acc_b, now_b, script_b, True))

    def script_c(a):
        t = datetime(2026, 10, 9, 22, 0, 0, tzinfo=timezone.utc)
        t_old = datetime(2026, 10, 8, 1, 0, 0, tzinfo=timezone.utc)
        return [[], [_enc(a._primary_gen[3300], t, -22.9068, -43.1729, 33, 0, 2)], [], [], [_enc(a._primary_gen[2500], t_old, -22.91, -43.18, 50, 8, 1)]]

    scenarios.append(_run_rolling("chunked_full_history", acc_b, now_b, script_c, False))
    scenarios.append(_run_rolling("chunked_nothing_found", acc_b, now_b, lambda a: [], True))

    # static (non-rolling) keys: one `fetch` entry per key, all as primary ids
    k1, k2 = KeyPair(seed("static1", 28), name="S1"), KeyPair(seed("static2", 28), name="S2")
    t = datetime(2026, 10, 3, 9, 0, tzinfo=timezone.utc)
    reps = [_enc(k1, t, 10.0, 20.0, 7, 1, 3), _enc(k2, t + timedelta(minutes=5), 11.0, 21.0, 8, 2, 2), _enc(k1, t + timedelta(minutes=30), 10.5, 20.5, 9, 3, 1)]
    _freeze(now_a)
    fake = _FakeAccount([reps])
    res = asyncio.run(LocationReportsFetcher(fake)._fetch_key_reports([k1, k2]))
    static = {
        "keys": [k1.private_key_b64, k2.private_key_b64], "now": now_a.isoformat(),
        "calls": [[{"primary": p, "secondary": s} for p, s in call] for call in fake.calls],
        "replies": [[{"hashed": B64(h), "payload": B64(p)} for h, p in reps]],
        "reports": {k.private_key_b64: _summ_reports(rs) for k, rs in res.items()},
    }
    dump("fetch.json", {"rolling": scenarios, "static": static})


if __name__ == "__main__":
    gen_keys()
    gen_alignment()
    gen_accessory_json()
    gen_decrypt()
    gen_fetch()
    print("fixtures written to", OUT)
